/**
 * xui shadcn theme - MUI v9 restyled 1:1 to shadcn/ui defaults.
 * Self-contained: imports only from @mui/material/styles (no relative imports).
 * Token source: apps/showcase/src/index.css generated by shadcn CLI
 * (style radix-nova, base color neutral, css variables).
 */
import { createTheme, type CssVarsTheme, type Theme } from "@mui/material/styles"
import { Check, ChevronDown } from "lucide-react"
// createElement (not JSX) because this file is a plain .ts module - JSX syntax is only
// valid in .tsx files, and this file's name/extension is fixed by the constraint that only
// packages/xui/src/themes/shadcn.ts may change. "react" itself is not a new external
// dependency - it is already xui's peerDependency/devDependency, required transitively by
// every MUI component this theme already configures.
import { createElement } from "react"

// ---------------------------------------------------------------------------
// Module augmentation: shared semantic vocabulary (spec: every future theme
// fills these same slots).
// ---------------------------------------------------------------------------
declare module "@mui/material/styles" {
  // Native background/text slots don't ship *Channel fields (MUI only types
  // them on the vars-internal shape, not the public Palette/PaletteOptions),
  // so we add them here to match what setColorChannel() actually populates.
  interface TypeBackground {
    defaultChannel: string
    paperChannel: string
  }
  interface TypeText {
    primaryChannel: string
    secondaryChannel: string
  }
  interface Palette {
    muted: { main: string; mainChannel: string; contrastText: string }
    accent: { main: string; mainChannel: string; contrastText: string }
    popover: { main: string; mainChannel: string; contrastText: string }
    card: { main: string; mainChannel: string; contrastText: string }
    border: string
    input: string
    ring: string
    dividerChannel: string
  }
  interface PaletteOptions {
    muted?: { main: string; mainChannel?: string; contrastText: string }
    accent?: { main: string; mainChannel?: string; contrastText: string }
    popover?: { main: string; mainChannel?: string; contrastText: string }
    card?: { main: string; mainChannel?: string; contrastText: string }
    border?: string
    input?: string
    ring?: string
    dividerChannel?: string
  }
  // TouchRipple is a real themeable slot at runtime (ButtonBase/TouchRipple.js declares
  // `name: 'MuiTouchRipple', slot: 'Root'`) but MUI omits it from the public `Components` map,
  // so declaring it here is what lets the ripple backstop below typecheck.
  interface ComponentNameToClassKey {
    MuiTouchRipple: "root" | "ripple" | "rippleVisible" | "child" | "childLeaving"
  }
  interface Components {
    MuiTouchRipple?: {
      styleOverrides?: { root?: { display?: "none" } }
    }
  }
}

declare module "@mui/material/Button" {
  interface ButtonPropsVariantOverrides {
    link: true
  }
}

declare module "@mui/material/IconButton" {
  // shadcn's icon button comes in four sizes and MUI ships three. `icon`, `icon-sm` and `icon-lg`
  // map onto medium/small/large; `icon-xs` - the 24px square the InputGroup and Combobox clear
  // controls are built from - has nowhere left to go, so the theme adds it as a real size rather
  // than asking every call site to restate the dimensions.
  interface IconButtonPropsSizeOverrides {
    xsmall: true
  }
}

// ---------------------------------------------------------------------------
// Design tokens - transcribed from shadcn ground truth. Generated file wins.
// ---------------------------------------------------------------------------
